xpath.script:
odoo.define('fet_user_login_detail.after_login', function (require) {
    "use strict";

    var session = require('web.session');

    if (session.is_authenticated()) {
        // User is already logged in
        $.ajax({
            url: '/web/session/after_login',
            type: 'POST',
            dataType: 'json',
            data: {},
            success: function(data) {
                console.log('Session tracked:', data);
            }
        });
    }
});
